#!/usr/bin/env python3
"""Make an animation-studio project render fast (on by default): raw RGBA frames instead of PNGs, and the GPU's
video encoder (NVENC) for the frames and the final mux when there is an NVIDIA GPU (x264 on CPU otherwise).

    python3 scripts/reels/fast_render.py <project folder>     # patches <project>/engine/render.js in place

Measured on the EGM explainer (76 s, 1080x1920): PNG-encoding a frame in Chrome took ~75 ms against ~14 ms to draw it;
raw frames took the same 4-core box from 7 to 20 fps. Turn off per render with RENDER_RAW=0 / RENDER_GPU=0.
Safe to run twice; stops with a clear message if the skill's renderer changed under it.
"""
import sys, pathlib
EDITS = [('\n// Every Chrome this script launches is tracked and killed on exit or failure — and ONLY those.\n', "\n// ---------- fast frames (on by default): raw pixels instead of PNGs, and the GPU's video encoder when there is one ----------\n// Profiled on a 1080x1920 frame: drawing ~14 ms, but PNG-encoding it in Chrome ~75 ms, decoding it again in ffmpeg ~25 ms,\n// and x264 ~42 ms. So frames go out as raw RGBA (the same pixels, nothing lost) POSTed to the page's own local server,\n// and ffmpeg encodes with NVENC (h264_nvenc) when an NVIDIA GPU is there, x264 otherwise.\n//   RENDER_RAW=0  back to PNG frames      RENDER_GPU=0  never use the GPU encoder\nconst RAW = process.env.RENDER_RAW !== '0';\nconst RAW_SINK = new Map(); // key -> resolve(buffer)\nHOOKS.push((req, res) => {\n  if (req.method !== 'POST' || !req.url.startsWith('/__frame?k=')) return false;\n  const key = decodeURIComponent(req.url.slice('/__frame?k='.length));\n  const chunks = [];\n  req.on('data', (d) => chunks.push(d));\n  req.on('end', () => { const done = RAW_SINK.get(key); RAW_SINK.delete(key); res.writeHead(204); res.end(); if (done) done(Buffer.concat(chunks)); });\n  return true;\n});\nlet NVENC = null;\n// Colab keeps the NVIDIA driver's libraries (libnvidia-encode, libcuda) in /usr/lib64-nvidia: make sure ffmpeg can see them\n// even when LD_LIBRARY_PATH was set to something else (the Chrome libraries, say).\nif (fs.existsSync('/usr/lib64-nvidia') && !(process.env.LD_LIBRARY_PATH || '').split(':').includes('/usr/lib64-nvidia')) {\n  process.env.LD_LIBRARY_PATH = [process.env.LD_LIBRARY_PATH, '/usr/lib64-nvidia'].filter(Boolean).join(':');\n}\nfunction hasNvenc() {\n  if (NVENC !== null) return NVENC;\n  NVENC = false;\n  if (process.env.RENDER_GPU === '0') return NVENC;\n  try { execFileSync(FFMPEG, ['-v', 'error', '-f', 'lavfi', '-i', 'color=c=black:s=256x256:r=30', '-frames:v', '3', '-c:v', 'h264_nvenc', '-f', 'null', '-'], { stdio: 'ignore', timeout: 20000 }); NVENC = true; } catch (e) { /* no NVIDIA GPU or no NVENC build */ }\n  return NVENC;\n}\n/** Encoder arguments for a quality level (x264 CRF; NVENC's constant-quality is matched to it). */\nfunction encoderArgs(crf, preset) {\n  if (hasNvenc()) return ['-c:v', 'h264_nvenc', '-preset', 'p6', '-tune', 'hq', '-rc', 'vbr', '-cq', String(Math.max(1, crf - 1)), '-b:v', '0', '-spatial-aq', '1', '-pix_fmt', 'yuv420p', '-profile:v', 'high', '-g', '60'];\n  return ['-c:v', 'libx264', '-preset', preset, '-crf', String(crf), '-pix_fmt', 'yuv420p', '-profile:v', 'high', '-g', '60'];\n}\nlet rawSeq = 0;\n/** One frame as raw RGBA: drawn, read back, POSTed to our server (no PNG, no base64). */\nasync function grabRaw(w, t, scale = SCALE) {\n  const key = `${w.tag || 'w'}-${++rawSeq}`;\n  const got = new Promise((r) => RAW_SINK.set(key, r));\n  await evaluate(w.c, `(async () => { window.renderAt(${t}, 'none', ${scale}); const c = document.getElementById('c'); const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data; await fetch('/__frame?k=${key}', { method: 'POST', body: d }); return 1; })()`);\n  return got;\n}\n\n// Every Chrome this script launches is tracked and killed on exit or failure — and ONLY those.\n"), ('  try {\n    return await attach(proc, ws, dir, tag, url, opts);\n  } catch (e) {\n', '  try {\n    const w = await attach(proc, ws, dir, tag, url, opts);\n    w.tag = tag;\n    return w;\n  } catch (e) {\n'), ("    const seg = path.join(segDir, `seg${String(k).padStart(2, '0')}.mp4`);\n    const ff = spawn(FFMPEG, ['-v', 'error', '-y', '-f', 'image2pipe', '-framerate', String(FPS), '-c:v', fmt === 'jpeg' ? 'mjpeg' : 'png', '-i', '-',\n      '-c:v', 'libx264', '-preset', preset, '-crf', String(crf), '-pix_fmt', 'yuv420p', '-profile:v', 'high', '-g', '60', seg], { stdio: ['pipe', 'inherit', 'inherit'] });\n    let ffExit = null;\n", "    const seg = path.join(segDir, `seg${String(k).padStart(2, '0')}.mp4`);\n    const raw = RAW && fmt === 'png';\n    const cw = 2 * Math.ceil((FW * SCALE) / 2), ch = 2 * Math.ceil((FH * SCALE) / 2);\n    const input = raw ? ['-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${cw}x${ch}`, '-framerate', String(FPS), '-i', '-']\n      : ['-f', 'image2pipe', '-framerate', String(FPS), '-c:v', fmt === 'jpeg' ? 'mjpeg' : 'png', '-i', '-'];\n    const ff = spawn(FFMPEG, ['-v', 'error', '-y', ...input, ...encoderArgs(crf, preset), seg], { stdio: ['pipe', 'inherit', 'inherit'] });\n    let ffExit = null;\n"), ('      if (ffExit !== null) break; // ffmpeg is gone: stop feeding it\n      const img = await grab(w, f / FPS, fmt);\n      // wait for room in the pipe OR for ffmpeg to exit, whichever comes first (never hang)\n', "      if (ffExit !== null) break; // ffmpeg is gone: stop feeding it\n      const img = RAW && fmt === 'png' ? await grabRaw(w, f / FPS) : await grab(w, f / FPS, fmt);\n      // wait for room in the pipe OR for ffmpeg to exit, whichever comes first (never hang)\n"), ("      execFileSync(FFMPEG, ['-v', 'error', '-y', '-i', VIDEO, '-i', path.join(OUT, 'music.wav'), ...subs, '-map', '0:v', '-map', '1:a', ...(subs.length ? ['-map', '2:s', '-c:s', 'mov_text'] : []),\n        '-c:v', 'libx264', '-preset', 'slow', '-crf', '18', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', '-c:a', 'aac', '-b:a', '256k', '-shortest', file], { stdio: 'inherit' });\n      if (args.includes('--subs') && !subs.length) console.log('(no out/*.srt yet: run node engine/render.js srt first)');\n", "      execFileSync(FFMPEG, ['-v', 'error', '-y', '-i', VIDEO, '-i', path.join(OUT, 'music.wav'), ...subs, '-map', '0:v', '-map', '1:a', ...(subs.length ? ['-map', '2:s', '-c:s', 'mov_text'] : []),\n        ...(hasNvenc() ? ['-c:v', 'h264_nvenc', '-preset', 'p7', '-tune', 'hq', '-rc', 'vbr', '-cq', '18', '-b:v', '0', '-spatial-aq', '1', '-pix_fmt', 'yuv420p', '-profile:v', 'high'] : ['-c:v', 'libx264', '-preset', 'slow', '-crf', '18', '-pix_fmt', 'yuv420p']), '-movflags', '+faststart', '-c:a', 'aac', '-b:a', '256k', '-shortest', file], { stdio: 'inherit' });\n      if (args.includes('--subs') && !subs.length) console.log('(no out/*.srt yet: run node engine/render.js srt first)');\n"), ('    const workers = parseInt(args[0] || String(Math.max(2, os.cpus().length - 1)), 10);\n    const { frames, secs } = await renderRange(0, Math.round(DURATION * FPS), workers, VIDEO);\n', "    const workers = parseInt(args[0] || String(Math.max(2, os.cpus().length - 1)), 10);\n    console.log(`frames: ${RAW ? 'raw RGBA' : 'PNG'} · encoder: ${hasNvenc() ? 'GPU (h264_nvenc)' : 'CPU (x264)'} · ${workers} workers`);\n    const { frames, secs } = await renderRange(0, Math.round(DURATION * FPS), workers, VIDEO);\n")]
p = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else '.') / 'engine' / 'render.js'
s = p.read_text()
if 'RENDER_RAW' in s:
    print(f'{p}: already fast'); sys.exit(0)
for old, new in EDITS:
    if s.count(old) != 1:
        sys.exit(f'{p}: the renderer changed (anchor not found once): {old.strip().splitlines()[0][:90]!r}')
    s = s.replace(old, new)
p.write_text(s)
print(f'{p}: fast frames on (raw RGBA; NVENC when an NVIDIA GPU is there)')
